-- ======================================================================
--  IRON LEAGUE — a seat you can free, and a past nobody can edit
--
--  Paste the whole file into the Supabase SQL editor and press RUN, or apply
--  it over the API. Safe to run twice. NOTHING LOGGED IS TOUCHED and no
--  points are rewritten.
--
--  GENERATED by tools/build_launchgate_migration.py, which lifts every
--  function below out of supabase/schema.sql. Edit there and re-run it,
--  never here.
--
--  WHY, PART ONE: HISTORY HAS TO OUTLIVE A MEMBERSHIP
--  weekly_history inner-joined league_members, purely to fetch joined_at for
--  the tie-break. The effect nobody noticed: anybody who LEFT a league
--  stopped having won the weeks they won. The hall of fame re-ranked, crowns
--  moved to the runner-up, the season table reshuffled and the cup reseeded —
--  all retroactively, all silently. A roster is a fact about now; a finished
--  week is a fact about then, and leaving must not be able to edit it.
--
--  league_roster() replaces that join: the people in a league now, PLUS
--  anybody who ever logged into it, with joined_at falling back to their
--  first workout there once the membership row is gone. league_wins and
--  league_season now read it too, and both gained a `member` column so a
--  board can show somebody who earned their crowns and then left, marked as
--  no longer in the league. Somebody who left without ever scoring has no
--  history to show and falls out on their own.
--
--  WHY, PART TWO: A SEAT YOU CAN FREE WITHOUT DELETING ANYBODY
--  profiles.dormant_at parks an account. It is NOT a deletion:
--
--    · everything they logged stays, and still counts for everyone else
--    · every week they won stays theirs, in the hall of fame and the crowns
--    · their leagues still list them, so putting them back is one switch
--    · they stop counting against the cap, and drop off live boards
--
--  That last line is what frees the seat — globally, and in each league's 36.
--
--  app_settings.user_cap is the cap. A row, not a constant, so it can be
--  raised from the control room at three in the morning. null means no cap,
--  which is where it starts, so applying this file changes nothing until
--  somebody sets a number.
--
--  Coming back to a parked account needs a free seat, same as anybody else
--  arriving: restore_profile() and wake_me() both raise APP_FULL rather than
--  letting the app quietly go over. Nothing is lost by waiting.
-- ======================================================================
begin;
set local check_function_bodies = off;

-- ------------------------------------------------- the cap, as a row ---
create table if not exists public.app_settings (
  only_row   boolean primary key default true check (only_row),
  user_cap   int check (user_cap is null or user_cap >= 0),
  updated_at timestamptz not null default now()
);
insert into public.app_settings (only_row, user_cap) values (true, null)
  on conflict (only_row) do nothing;
alter table public.app_settings enable row level security;
drop policy if exists app_settings_read on public.app_settings;
create policy app_settings_read on public.app_settings for select
  to anon, authenticated using (true);

-- --------------------------------------------- parked, not deleted ---
alter table public.profiles add column if not exists dormant_at timestamptz;

-- --------------------------------------- shapes that changed ---
drop function if exists public.league_wins(p_league uuid) cascade;
drop function if exists public.league_season(p_league uuid, p_season int) cascade;
drop function if exists public.admin_players() cascade;

-- --------------------------------------------------------- league_roster ---
create or replace function public.league_roster(p_league uuid)
returns table (profile_id uuid, joined_at timestamptz, member boolean)
language sql stable security definer set search_path = public as $fn$
  with mem as (
    select m.profile_id, m.joined_at
    from public.league_members m where m.league_id = p_league),
  logged as (
    select w.profile_id, min(w.created_at) as first_log
    from public.workouts w where w.league_id = p_league group by 1)
  select coalesce(m.profile_id, l.profile_id),
         coalesce(m.joined_at, l.first_log),
         -- `member` means "counts right now", so a parked account reads the
         -- same as somebody who left: still in the history, off the roster.
         m.profile_id is not null and p.dormant_at is null
  from mem m full outer join logged l on l.profile_id = m.profile_id
  join public.profiles p on p.id = coalesce(m.profile_id, l.profile_id)
$fn$;

-- -------------------------------------------------------- weekly_history ---
create or replace function public.weekly_history(p_league uuid)
returns table (week_start date, profile_id uuid, display_name text, avatar text,
               points numeric, entries bigint, joined_at timestamptz)
language sql stable security definer set search_path = public as $fn$
  select t.week_start, t.profile_id, t.display_name, t.avatar,
         (t.pts + coalesce(cb.bonus, 0) + coalesce(bb.bounty, 0))::numeric,
         t.n, t.joined_at
  from (
    select e.week_start, p.id as profile_id, p.display_name, p.avatar,
           sum(public.tier_points(e.raw, e.cap)) as pts, sum(e.n) as n,
           m.joined_at
    from (select w.week_start, w.profile_id, w.exercise_key,
                 sum(w.points) as raw, count(*) as n, max(x.cap) as cap
          from public.workouts w
          left join public.exercises x on x.key = w.exercise_key
          where w.league_id = p_league
            and w.week_start < public.current_week_start()
          group by 1, 2, 3) e
    join public.profiles p on p.id = e.profile_id
    join public.league_roster(p_league) m on m.profile_id = p.id
    where public.is_member(p_league)
    group by e.week_start, p.id, p.display_name, p.avatar, m.joined_at
  ) t
  left join lateral (
    select bonus from public.week_combo_bonus(p_league, t.week_start) b
    where b.profile_id = t.profile_id
  ) cb on true
  left join lateral (
    select bounty from public.week_bounty_points(p_league, t.week_start) b
    where b.profile_id = t.profile_id
  ) bb on true
  order by t.week_start desc, 5 desc, t.joined_at asc
$fn$;

-- ----------------------------------------------------------- league_wins ---
create or replace function public.league_wins(p_league uuid)
returns table (profile_id uuid, display_name text, avatar text,
               wins int, last_win date, weeks int, banner text,
               pinned_badges text[], name_color text, mine boolean,
               member boolean)
language sql stable security definer set search_path = public as $fn$
  with done as (
    select h.week_start, h.profile_id,
           row_number() over (partition by h.week_start
                              order by h.points desc, h.joined_at asc) as rk
    from public.weekly_history(p_league) h
    where h.week_start < public.current_week_start()
  ),
  won as (select profile_id, count(*)::int n, max(week_start) last
          from done where rk = 1 group by 1),
  n as (select count(distinct week_start)::int c from done)
  -- The roster, not the membership: a crown is earned, and somebody who won
  -- five weeks and then left still won them. Anybody who never scored and is
  -- no longer here simply has no history to show, so they drop out on their
  -- own rather than needing a rule.
  select p.id, p.display_name, p.avatar,
         coalesce(w.n, 0), w.last, (select c from n),
         p.banner, p.pinned_badges, p.name_color,
         p.id = public.my_profile_id(), m.member
  from public.league_roster(p_league) m
  join public.profiles p on p.id = m.profile_id
  left join won w on w.profile_id = p.id
  where public.is_member(p_league)
    and (m.member or w.n is not null)
  order by coalesce(w.n, 0) desc, w.last desc nulls last, m.joined_at
$fn$;

-- --------------------------------------------------------- league_season ---
create or replace function public.league_season(p_league uuid, p_season int default null)
returns table (profile_id uuid, display_name text, avatar text, banner text,
               pinned_badges text[], name_color text, points numeric,
               weeks int, wins int, best_rank int, lifetime_wins int,
               mine boolean, member boolean)
language sql stable security definer set search_path = public as $fn$
  with ranked as (
    select h.week_start, h.profile_id,
           row_number() over (partition by h.week_start
                              order by h.points desc, h.joined_at asc)::int as rk,
           public.season_index(p_league, h.week_start) as season
    from public.weekly_history(p_league) h
    where h.week_start < public.current_week_start()
  ),
  -- an off-season week is tagged null by season_index and never joins a table
  pick as (select coalesce(p_season,
                  (select max(season) from ranked where season is not null), 0)::int as s),
  season_rows as (select * from ranked
                  where season is not null and season = (select s from pick)),
  -- crowns follow the person across every season, so the row can still say
  -- what somebody has done here in total
  life as (select profile_id, count(*)::int n from ranked where rk = 1 group by 1)
  select p.id, p.display_name, p.avatar, p.banner, p.pinned_badges, p.name_color,
         coalesce(sum(public.rank_points(sr.rk)), 0)::numeric,
         count(sr.week_start)::int,
         (count(sr.week_start) filter (where sr.rk = 1))::int,
         min(sr.rk),
         coalesce(max(lf.n), 0)::int,
         p.id = public.my_profile_id(), bool_and(m.member)
  -- The roster, so a season somebody played half of still shows what they
  -- scored in it. Somebody who left without ever scoring has nothing to show
  -- and falls out here rather than sitting on the table at zero.
  from public.league_roster(p_league) m
  join public.profiles p on p.id = m.profile_id
  left join season_rows sr on sr.profile_id = p.id
  left join life lf on lf.profile_id = p.id
  where public.is_member(p_league)
  group by p.id, p.display_name, p.avatar, p.banner, p.pinned_badges,
           p.name_color, m.joined_at
  having bool_and(m.member) or count(sr.week_start) > 0
  order by 7 desc, 9 desc, 10 asc nulls last, m.joined_at
$fn$;

-- ---------------------------------------------------- league_leaderboard ---
create or replace function public.league_leaderboard(p_league uuid, p_week date default null)
returns table (profile_id uuid, display_name text, avatar text, points numeric,
               base_points numeric, bonus numeric, entries bigint,
               joined_at timestamptz, lifetime numeric, banner text,
               pinned_badges text[], name_color text)
language sql stable security definer set search_path = public as $fn$
  -- `lifetime` drives the rank banner on each row. Like divisions and duel
  -- records it is derived on read, so there is nothing to store or award.
  with wk as (select coalesce(p_week, public.current_week_start()) as w),
  cb as (select * from public.week_combo_bonus(p_league, (select w from wk))),
  bb as (select * from public.week_bounty_points(p_league, (select w from wk))),
  -- The week, already through the repetition discount of section 2b, so the
  -- board shows what a week is worth rather than what it was logged at.
  ws as (select * from public.week_scored(p_league, (select w from wk))),
  -- Lifetime follows the person, not the league, and is discounted the same
  -- way — week by week, so a year of training is never run through one curve.
  lt as (select * from public.life_scored_all())
  select p.id, p.display_name, p.avatar,
         (coalesce(ws.points, 0) + coalesce(cb.bonus, 0)
                                 + coalesce(bb.bounty, 0))::numeric,
         coalesce(ws.points, 0)::numeric,
         (coalesce(cb.bonus, 0) + coalesce(bb.bounty, 0))::numeric,
         coalesce(ws.entries, 0), m.joined_at,
         coalesce(lt.points, 0)::numeric, p.banner, p.pinned_badges,
         p.name_color
  from public.league_members m
  join public.profiles p on p.id = m.profile_id
  left join ws on ws.profile_id = p.id
  left join cb on cb.profile_id = p.id
  left join bb on bb.profile_id = p.id
  left join lt on lt.profile_id = p.id
  where m.league_id = p_league and public.is_member(p_league)
    and p.dormant_at is null
  order by 4 desc, 8 asc
$fn$;

-- -------------------------------------------------------- league_streaks ---
create or replace function public.league_streaks(p_league uuid, p_min numeric default 20)
returns table (profile_id uuid, display_name text, avatar text, banner text,
               current_streak int, best_streak int, active_days int)
language sql stable security definer set search_path = public as $fn$
  with days as (
    select w.profile_id,
           (w.created_at at time zone public.app_timezone())::date as d,
           sum(w.points) as pts
    from public.workouts w
    where w.league_id = p_league
    group by 1, 2
    having sum(w.points) >= p_min
  ),
  grp as (
    select profile_id, d,
           d - (row_number() over (partition by profile_id order by d))::int as run
    from days
  ),
  runs as (
    select profile_id, run, count(*)::int as len, max(d) as ended
    from grp group by 1, 2
  ),
  today as (select (now() at time zone public.app_timezone())::date as t)
  select p.id, p.display_name, p.avatar, p.banner,
         coalesce(max(r.len) filter (where r.ended >= (select t from today) - 1), 0)::int,
         coalesce(max(r.len), 0)::int,
         coalesce(sum(r.len), 0)::int
  from public.league_members m
  join public.profiles p on p.id = m.profile_id
  left join runs r on r.profile_id = p.id
  where m.league_id = p_league and public.is_member(p_league)
    and p.dormant_at is null
  group by p.id, p.display_name, p.avatar, p.banner
  order by 5 desc, 6 desc, 7 desc
$fn$;

-- ------------------------------------------------------------ my_leagues ---
create or replace function public.my_leagues()
returns table (id uuid, name text, code text, owner_id uuid, members int,
               max_members int, joined_at timestamptz,
               badge jsonb, rest_dow int[], season_weeks int, catchup_dow int,
               created_at timestamptz)
language sql stable security definer set search_path = public as $fn$
  select l.id, l.name, l.code, l.owner_id,
         (select count(*)::int from public.league_members m2
           join public.profiles p2 on p2.id = m2.profile_id
          where m2.league_id = l.id and p2.dormant_at is null),
         l.max_members, m.joined_at,
         l.badge, l.rest_dow, l.season_weeks, l.catchup_dow, l.created_at
  from public.leagues l
  join public.league_members m on m.league_id = l.id
  where m.profile_id = public.my_profile_id()
  order by m.joined_at
$fn$;

-- -------------------------------------------------------- league_preview ---
create or replace function public.league_preview(p_code text)
returns table (id uuid, name text, code text, members int, max_members int)
language sql security definer set search_path = public as $fn$
  select l.id, l.name, l.code,
         (select count(*)::int from public.league_members m
           join public.profiles p on p.id = m.profile_id
          where m.league_id = l.id and p.dormant_at is null),
         l.max_members
  from public.leagues l
  where l.code = upper(btrim(p_code))
$fn$;

-- ----------------------------------------------- enforce_league_capacity ---
create or replace function public.enforce_league_capacity() returns trigger
language plpgsql set search_path = public as $fn$
declare
  cap int;
  taken int;
begin
  select max_members into cap from public.leagues where id = new.league_id for update;
  if cap is null then
    raise exception 'League not found';
  end if;
  -- Parked accounts do not hold a seat: that is the point of parking one.
  select count(*) into taken
    from public.league_members m
    join public.profiles p on p.id = m.profile_id
   where m.league_id = new.league_id and p.dormant_at is null;
  if taken >= cap then
    raise exception 'LEAGUE_FULL';
  end if;
  return new;
end $fn$;

-- ---------------------------------------------------------- signup_state ---
create or replace function public.signup_state()
returns table (cap int, used int, is_full boolean)
language sql stable security definer set search_path = public as $fn$
  select s.user_cap,
         (select count(*)::int from public.profiles where dormant_at is null),
         s.user_cap is not null
           and (select count(*) from public.profiles where dormant_at is null)
               >= s.user_cap
  from public.app_settings s where s.only_row
$fn$;

-- ----------------------------------------------------------- app_is_full ---
create or replace function public.app_is_full() returns boolean
language sql stable security definer set search_path = public as $fn$
  select coalesce((select is_full from public.signup_state()), false)
$fn$;

-- -------------------------------------------------------- create_profile ---
create or replace function public.create_profile(p_name text)
returns public.profiles
language plpgsql security definer set search_path = public as $fn$
declare
  p public.profiles;
begin
  if auth.uid() is null then raise exception 'NOT_SIGNED_IN'; end if;
  select * into p from public.profiles where user_id = auth.uid();
  if found then return p; end if;
  -- Checked here rather than only on the phone, because the phone is not the
  -- thing holding the line.
  if public.app_is_full() then raise exception 'APP_FULL'; end if;
  insert into public.profiles (user_id, display_name)
  values (auth.uid(), btrim(p_name))
  returning * into p;
  return p;
end $fn$;

-- ------------------------------------------------------- restore_profile ---
create or replace function public.restore_profile(p_code text)
returns public.profiles
language plpgsql security definer set search_path = public as $fn$
declare
  target   public.profiles;
  existing public.profiles;
  logs     int;
begin
  if auth.uid() is null then raise exception 'NOT_SIGNED_IN'; end if;

  select * into target from public.profiles
   where restore_code = upper(btrim(p_code));
  if not found then raise exception 'BAD_CODE'; end if;
  if target.user_id = auth.uid() then return target; end if;

  -- If this device already made a throwaway profile, drop it (only if unused).
  select * into existing from public.profiles where user_id = auth.uid();
  if found then
    select count(*) into logs from public.workouts where profile_id = existing.id;
    if logs > 0 then raise exception 'DEVICE_HAS_DATA'; end if;
    delete from public.profiles where id = existing.id;
  end if;

  -- Coming back to a parked account. They kept everything — the rank, the
  -- badges, every week they won — but the seat went to somebody else, so
  -- they only get it back if one is free.
  if target.dormant_at is not null and public.app_is_full() then
    raise exception 'APP_FULL';
  end if;

  update public.profiles set user_id = auth.uid(), dormant_at = null
   where id = target.id returning * into target;
  return target;
end $fn$;

-- --------------------------------------------------------------- wake_me ---
create or replace function public.wake_me() returns public.profiles
language plpgsql security definer set search_path = public as $fn$
declare p public.profiles;
begin
  select * into p from public.profiles where user_id = auth.uid();
  if not found then raise exception 'NO_PROFILE'; end if;
  if p.dormant_at is null then return p; end if;
  if public.app_is_full() then raise exception 'APP_FULL'; end if;
  update public.profiles set dormant_at = null
   where id = p.id returning * into p;
  return p;
end $fn$;

-- -------------------------------------------------------- admin_overview ---
create or replace function public.admin_overview()
returns table (cap int, used int, dormant int, is_full boolean, leagues int)
language sql stable security definer set search_path = public as $fn$
  select s.cap, s.used,
         (select count(*)::int from public.profiles where dormant_at is not null),
         s.is_full,
         (select count(*)::int from public.leagues)
  from public.signup_state() s
  where public.is_admin()
$fn$;

-- --------------------------------------------------------- admin_set_cap ---
create or replace function public.admin_set_cap(p_cap int) returns int
language plpgsql security definer set search_path = public as $fn$
begin
  if not public.is_admin() then raise exception 'Not allowed'; end if;
  if p_cap is not null and p_cap < 0 then raise exception 'A cap cannot be negative'; end if;
  update public.app_settings set user_cap = p_cap, updated_at = now() where only_row;
  return p_cap;
end $fn$;

-- ----------------------------------------------------- admin_set_dormant ---
create or replace function public.admin_set_dormant(p_profile uuid, p_dormant boolean)
returns public.profiles
language plpgsql security definer set search_path = public as $fn$
declare p public.profiles;
begin
  if not public.is_admin() then raise exception 'Not allowed'; end if;
  if p_profile = public.my_profile_id() then
    raise exception 'You cannot park your own account from here';
  end if;
  -- Waking somebody needs a free seat, same as anybody else arriving.
  if not p_dormant and public.app_is_full() then
    raise exception 'APP_FULL';
  end if;
  update public.profiles
     set dormant_at = case when p_dormant then now() else null end
   where id = p_profile returning * into p;
  if not found then raise exception 'No such profile'; end if;
  return p;
end $fn$;

-- --------------------------------------------------------- admin_players ---
create or replace function public.admin_players()
returns table (id uuid, display_name text, avatar text, restore_code text,
               leagues int, workouts bigint, lifetime numeric, week_points numeric,
               last_log timestamptz, created_at timestamptz, is_admin boolean,
               dormant_at timestamptz)
language sql stable security definer set search_path = public as $fn$
  with wk as (select public.current_week_start() as w),
  lg as (select distinct league_id from public.league_members),
  base as (
    select e.profile_id, e.league_id,
           sum(public.tier_points(e.raw, e.cap)) as pts
    from (select x.profile_id, x.league_id, x.exercise_key,
                 sum(x.points) as raw, max(ex.cap) as cap
          from public.workouts x
          left join public.exercises ex on ex.key = x.exercise_key
          where x.week_start = (select w from wk)
          group by 1, 2, 3) e
    group by 1, 2),
  cb as (
    select l.league_id, c.profile_id, c.bonus
    from lg l, lateral public.week_combo_bonus(l.league_id, (select w from wk)) c),
  bb as (
    select l.league_id, b.profile_id, b.bounty
    from lg l, lateral public.week_bounty_points(l.league_id, (select w from wk)) b),
  board as (
    select m.profile_id,
           max(coalesce(base.pts, 0) + coalesce(cb.bonus, 0)
                                     + coalesce(bb.bounty, 0)) as total
    from public.league_members m
    left join base on base.profile_id = m.profile_id and base.league_id = m.league_id
    left join cb   on cb.profile_id   = m.profile_id and cb.league_id   = m.league_id
    left join bb   on bb.profile_id   = m.profile_id and bb.league_id   = m.league_id
    group by 1)
  select p.id, p.display_name, p.avatar, p.restore_code,
         (select count(*)::int from public.league_members m where m.profile_id = p.id),
         (select count(distinct w.group_id) from public.workouts w where w.profile_id = p.id),
         coalesce((select lp.points from public.life_scored_all() lp
                   where lp.profile_id = p.id), 0),
         coalesce((select total from board where board.profile_id = p.id), 0)::numeric,
         (select max(w.created_at) from public.workouts w where w.profile_id = p.id),
         p.created_at, p.is_admin, p.dormant_at
  from public.profiles p
  where public.is_admin()
  order by p.created_at
$fn$;

-- -------------------------------------------------------- grants ---
revoke all on function public.create_profile(text)          from public, anon;
revoke all on function public.restore_profile(text)         from public, anon;
revoke all on function public.league_preview(text)          from public, anon;
revoke all on function public.my_leagues()                  from public, anon;
revoke all on function public.league_leaderboard(uuid,date) from public, anon;
revoke all on function public.weekly_history(uuid)          from public, anon;
revoke all on function public.league_roster(uuid)           from public, anon, authenticated;
revoke all on function public.app_is_full()                 from public, anon, authenticated;
revoke all on function public.admin_overview()              from public, anon;
revoke all on function public.admin_set_cap(int)            from public, anon;
revoke all on function public.admin_set_dormant(uuid,boolean) from public, anon;
revoke all on function public.wake_me()                     from public, anon;
revoke all on function public.league_wins(uuid)             from public, anon;
grant execute on function public.create_profile(text)          to authenticated;
grant execute on function public.restore_profile(text)         to authenticated;
grant execute on function public.league_preview(text)          to authenticated;
grant execute on function public.my_leagues()                  to authenticated;
grant execute on function public.league_leaderboard(uuid,date) to authenticated;
grant execute on function public.weekly_history(uuid)          to authenticated;
grant execute on function public.league_wins(uuid)             to authenticated;
grant execute on function public.league_season_info(uuid)      to authenticated;
grant execute on function public.league_season_state(uuid)     to authenticated;
